{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e9-preset-craft-vs-plain-t5-20260919T125605Z/cell-p60sZf/src/address.js","content":"/**
 * Cell address parsing, ordering and range expansion.
 *
 * A column is one or two letters (A..Z, AA..ZZ); a row is one to three
 * digits and must be at least 1. Columns and rows are both mapped to plain
 * integers so addresses can be compared and enumerated.
 */

const ADDRESS_RE = /^([A-Z]{1,2})([0-9]{1,3})$/

/** Bijective base-26 column letters to a 1-based integer (A=1, Z=26, AA=27, ...). */
export function colToNum(letters) {
  let n = 0
  for (const ch of letters) n = n * 26 + (ch.charCodeAt(0) - 64)
  return n
}

/** Inverse of colToNum. */
export function numToCol(n) {
  let s = ''
  while (n > 0) {
    const rem = (n - 1) % 26
    s = String.fromCharCode(65 + rem) + s
    n = Math.floor((n - 1) / 26)
  }
  return s
}

/**
 * Reads a word (already known to be letters possibly followed by digits, in
 * the general lexical sense) as an address. Returns null when the word is
 * not shaped like an address at all (so callers can tell "not an address"
 * from "an address outside the addressable range").
 */
export function readAddressWord(word) {
  const upper = word.toUpperCase()
  const m = ADDRESS_RE.exec(upper)
  if (!m) return null
  const col = colToNum(m[1])
  const row = Number(m[2])
  const inRange = row >= 1
  return { label: upper, col, row, inRange }
}

/** Compares two addresses by ascending column, then ascending row. */
export function compareAddr(a, b) {
  if (a.col !== b.col) return a.col - b.col
  return a.row - b.row
}

export function addrLabel(col, row) {
  return numToCol(col) + row
}

/**
 * Expands a range between two corners (in whichever order they were
 * written) into every covered address, in ascending column and then
 * ascending row order.
 */
export function expandRange(a, b) {
  const colMin = Math.min(a.col, b.col)
  const colMax = Math.max(a.col, b.col)
  const rowMin = Math.min(a.row, b.row)
  const rowMax = Math.max(a.row, b.row)
  const out = []
  for (let c = colMin; c <= colMax; c++) {
    for (let r = rowMin; r <= rowMax; r++) {
      out.push({ label: addrLabel(c, r), col: c, row: r })
    }
  }
  return out
}
"}

