{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e9-preset-craft-vs-plain-t5-20260919T125605Z/cell-p60sZf/src/sheet.js","content":"/**
 * Parses the sheet text format into a map from canonical address to its raw
 * (verbatim) content, in the order the cells were declared.
 */

import { readAddressWord } from './address.js'

export class SheetError extends Error {
  constructor(message) {
    super(message)
    this.name = 'SheetError'
  }
}

/**
 * Parses `text` (the whole standard input) into an ordered Map of
 * address -> raw content. Throws SheetError for a malformed address or a
 * cell declared twice, with a message ready to be reported to the user.
 */
export function parseSheet(text) {
  const lines = text.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  const cells = new Map()
  lines.forEach((rawLine, i) => {
    const lineNumber = i + 1
    let line = rawLine
    let start = 0
    while (start < line.length && (line[start] === ' ' || line[start] === '\t')) start++
    line = line.slice(start)
    if (line.length === 0 || line[0] === '#') return

    let end = 0
    while (end < line.length && line[end] !== ' ' && line[end] !== '\t') end++
    const addressToken = line.slice(0, end)
    let rest = end
    while (rest < line.length && (line[rest] === ' ' || line[rest] === '\t')) rest++
    // Only one run of separator whitespace is skipped, so stop right after
    // the first non-blank character of that run.
    if (rest > end) rest = end + 1
    while (rest < line.length && (line[rest] === ' ' || line[rest] === '\t')) {
      // Skip the rest of the single separating run.
      break
    }
    const content = line.slice(skipOneRun(line, end))

    const addr = readAddressWord(addressToken)
    if (!addr || !addr.inRange) {
      throw new SheetError(`error: line ${lineNumber}: invalid cell address ${addressToken}`)
    }
    if (cells.has(addr.label)) {
      throw new SheetError(`error: line ${lineNumber}: cell ${addr.label} is declared twice`)
    }
    cells.set(addr.label, content)
  })

  return cells
}

/** Index right after the single run of spaces/tabs starting at `from`. */
function skipOneRun(line, from) {
  let i = from
  if (i < line.length && (line[i] === ' ' || line[i] === '\t')) {
    while (i < line.length && (line[i] === ' ' || line[i] === '\t')) i++
  }
  return i
}
"}

