 * function argument; everywhere else the grammar rejects it, which is why
 * range parsing lives in parseArgument rather than in parseAtom.
 */

import { tokenize } from './lexer.js'

const COMPARISON_OPS = new Set(['=', '<>', '<', '<=', '>', '>='])

class ParseFail extends Error {}

class Parser {
  constructor(tokens) {
    this.tokens = tokens
    this.pos = 0
  }

  peek() {
    return this.tokens[this.pos]
  }

  at(type) {
    return this.peek().type === type
  }

  next() {
    return this.tokens[this.pos++]
  }

  expect(type) {
    if (!this.at(type)) throw new ParseFail()
    return this.next()
  }

  parseComparison() {
    let left = this.parseAdditive()
    while (COMPARISON_OPS.has(this.peek().type)) {
      const op = this.next().type
      const right = this.parseAdditive()
      left = { k: 'bin', op, left, right }
    }
    return left
  }

  parseAdditive() {
    let left = this.parseMultiplicative()
    while (this.at('+') || this.at('-')) {
      const op = this.next().type
      const right = this.parseMultiplicative()
      left = { k: 'bin', op, left, right }
    }
    return left
  }

  parseMultiplicative() {
    let left = this.parsePower()
    while (this.at('*') || this.at('/')) {
      const op = this.next().type
      const right = this.parsePower()
      left = { k: 'bin', op, left, right }
    }
    return left
  }

  parsePower() {
    const left = this.parseUnary()
    if (this.at('^')) {
      this.next()
      const right = this.parsePower()
      return { k: 'bin', op: '^', left, right }
    }
    return left
  }

  parseUnary() {
    if (this.at('-') || this.at('+')) {
      const op = this.next().type
      const expr = this.parseUnary()
      return { k: 'unary', op, expr }
    }
    return this.parseAtom()
  }

  parseAtom() {
    if (this.at('NUMBER')) return { k: 'num', v: this.next().value }
    if (this.at('(')) {
      this.next()
      const expr = this.parseComparison()
      this.expect(')')
      return expr
    }
    if (this.at('WORD')) {
      const word = this.next().value
      const upper = word.toUpperCase()
      if (this.at('(')) {
        this.next()
        const args = this.parseArgs()
        this.expect(')')
        return { k: 'call', name: upper, args }
      }
      if (upper === 'TRUE') return { k: 'bool', v: true }
      if (upper === 'FALSE') return { k: 'bool', v: false }
      return { k: 'addr', word }
    }
    throw new ParseFail()
  }

  parseArgs() {
    const args = []
    if (this.at(')')) return args
    args.push(this.parseArgument())
    while (this.at(',')) {
      this.next()
      args.push(this.parseArgument())
    }
    return args
  }

  parseArgument() {
    if (
      this.at('WORD') &&
      this.tokens[this.pos + 1].type === ':' &&
      this.tokens[this.pos + 2].type === 'WORD'
    ) {
      const from = this.next().value
      this.next()
      const to = this.next().value
