 * Sheet evaluator: turns raw cell content into values, following formula
 * references lazily and memoizing the result (and detecting cycles) per
 * cell.
 */

import { readAddressWord, expandRange } from './address.js'
import { parseFormula } from './parser.js'

const ERROR_TOKENS = new Set(['#DIV/0!', '#REF!', '#VALUE!', '#CYCLE!', '#NAME?', '#ERR!'])
const COMPARISON_OPS = new Set(['=', '<>', '<', '<=', '>', '>='])
const NUMBER_LITERAL_RE = /^-?[0-9]+(\.[0-9]+)?$/
const REDUCERS = new Set(['SUM', 'MIN', 'MAX', 'COUNT', 'AVG'])

const NUM = (v) => ({ t: 'num', v })
const TXT = (v) => ({ t: 'text', v })
const BOOL = (v) => ({ t: 'bool', v })
const ERR = (v) => ({ t: 'err', v })

function readLiteral(content) {
  if (content === '') return NUM(0)
  if (NUMBER_LITERAL_RE.test(content)) return NUM(Number(content))
  if (ERROR_TOKENS.has(content)) return ERR(content)
  return TXT(content)
}

/** Reads a value as a number for an arithmetic position. */
function toNumber(v) {
  if (v.t === 'num') return v
  if (v.t === 'bool') return NUM(v.v ? 1 : 0)
  if (v.t === 'text') return ERR('#VALUE!')
  return v // already an error
}

function rank(v) {
  return v.t === 'num' ? 0 : v.t === 'text' ? 1 : 2
}

function compareValues(a, b) {
  const ra = rank(a)
  const rb = rank(b)
  if (ra !== rb) return ra < rb ? -1 : 1
  if (a.t === 'bool') {
    const av = a.v ? 1 : 0
    const bv = b.v ? 1 : 0
    return av - bv
  }
  return a.v < b.v ? -1 : a.v > b.v ? 1 : 0
}

export class Evaluator {
  constructor(cells) {
    this.cells = cells
    this.formulas = new Map()
    this.cache = new Map()
    this.state = new Map()
  }

  getValue(address) {
    if (this.cache.has(address)) return this.cache.get(address)
    if (this.state.get(address) === 'in-progress') return ERR('#CYCLE!')
    this.state.set(address, 'in-progress')
    const content = this.cells.has(address) ? this.cells.get(address) : ''
    const value = this.cells.has(address) ? this.evalContent(content) : NUM(0)
    this.cache.set(address, value)
    this.state.set(address, 'done')
    return value
  }

  evalContent(content) {
    if (content.startsWith('=')) {
      const ast = parseFormula(content.slice(1))
      if (ast === null) return ERR('#ERR!')
      return this.evalNode(ast)
    }
    return readLiteral(content)
  }

  evalNode(node) {
    switch (node.k) {
      case 'num':
        return NUM(node.v)
      case 'bool':
        return BOOL(node.v)
      case 'addr':
        return this.evalAddr(node.word)
      case 'unary':
        return this.evalUnary(node)
      case 'bin':
        return COMPARISON_OPS.has(node.op) ? this.evalComparison(node) : this.evalArithmetic(node)
      case 'call':
        return this.evalCall(node)
      default:
        throw new Error(`unreachable node kind: ${node.k}`)
    }
  }

  evalAddr(word) {
    const addr = readAddressWord(word)
    if (!addr || !addr.inRange) return ERR('#REF!')
    return this.getValue(addr.label)
  }

  evalUnary(node) {
    const v = this.evalNode(node.expr)
    const n = toNumber(v)
    if (n.t === 'err') return n
    return NUM(node.op === '-' ? -n.v : n.v)
  }

  evalArithmetic(node) {
    const l = this.evalNode(node.left)
    const r = this.evalNode(node.right)
    if (l.t === 'err') return l
    if (r.t === 'err') return r
    const ln = toNumber(l)
    if (ln.t === 'err') return ln
    const rn = toNumber(r)
    if (rn.t === 'err') return rn
    if (node.op === '/' && rn.v === 0) return ERR('#DIV/0!')
    let result
    switch (node.op) {
      case '+':
        result = ln.v + rn.v
        break
      case '-':
        result = ln.v - rn.v
        break
      case '*':
        result = ln.v * rn.v
        break
      case '/':
        result = ln.v / rn.v
        break
      case '^':
        result = Math.pow(ln.v, rn.v)
        break
    }
    if (!Number.isFinite(result)) return ERR('#DIV/0!')
    return NUM(result)
  }

  evalComparison(node) {
    const l = this.evalNode(node.left)
    const r = this.evalNode(node.right)
    if (l.t === 'err') return l
    if (r.t === 'err') return r
    const cmp = compareValues(l, r)
    switch (node.op) {
      case '=':
        return BOOL(cmp === 0)
      case '<>':
        return BOOL(cmp !== 0)
      case '<':
        return BOOL(cmp < 0)
      case '<=':
        return BOOL(cmp <= 0)
      case '>':
        return BOOL(cmp > 0)
      case '>=':
        return BOOL(cmp >= 0)
    }
  }

  /** Evaluates a single argument to the list of values it contributes. */
  evalArg(arg) {
    if (arg.k === 'range') {
      const from = readAddressWord(arg.from)
      const to = readAddressWord(arg.to)
      if (!from || !from.inRange || !to || !to.inRange) return [ERR('#REF!')]
      return expandRange(from, to).map((cell) => this.getValue(cell.label))
    }
    return [this.evalNode(arg.expr)]
  }

  evalArgsFlat(args) {
    const values = []
    for (const arg of args) values.push(...this.evalArg(arg))
    return values
  }

  evalCall(node) {
    const { name, args } = node
    if (REDUCERS.has(name)) return this.evalReducer(name, args)
    if (name === 'ABS') return this.evalAbs(args)
    if (name === 'IF') return this.evalIf(args)
    return ERR('#NAME?')
  }

  evalReducer(name, args) {
    if (args.length < 1) return ERR('#ERR!')
    const values = this.evalArgsFlat(args)
    for (const v of values) if (v.t === 'err') return v
    if (name === 'COUNT') return NUM(values.filter((v) => v.t === 'num').length)
    const nums = []
    for (const v of values) {
      const n = toNumber(v)
      if (n.t === 'err') return n
      nums.push(n.v)
    }
    let result
    if (name === 'SUM') result = nums.reduce((a, b) => a + b, 0)
    else if (name === 'MIN') result = Math.min(...nums)
    else if (name === 'MAX') result = Math.max(...nums)
    else result = nums.reduce((a, b) => a + b, 0) / nums.length // AVG
    if (!Number.isFinite(result)) return ERR('#DIV/0!')
    return NUM(result)
  }

  evalAbs(args) {
    if (args.length !== 1) return ERR('#ERR!')
    const values = this.evalArg(args[0])
    for (const v of values) if (v.t === 'err') return v
    if (values.length !== 1) return ERR('#ERR!')
    const n = toNumber(values[0])
    if (n.t === 'err') return n
    const result = Math.abs(n.v)
    if (!Number.isFinite(result)) return ERR('#DIV/0!')
    return NUM(result)
  }

  evalIf(args) {
    if (args.length !== 3) return ERR('#ERR!')
    const condValues = this.evalArg(args[0])
    if (condValues.length !== 1) return ERR('#ERR!')
    const cond = condValues[0]
    if (cond.t === 'err') return cond
    let truth
    if (cond.t === 'bool') truth = cond.v
    else if (cond.t === 'num') truth = cond.v !== 0
    else return ERR('#VALUE!')
    const branch = truth ? args[1] : args[2]
    const values = this.evalArg(branch)
    if (values.length !== 1) return ERR('#ERR!')
    return values[0]
  }
}

export function formatValue(v) {
  if (v.t === 'err') return v.v
  if (v.t === 'bool') return v.v ? 'TRUE' : 'FALSE'
  if (v.t === 'text') return v.v
  return formatNumber(v.v)
}

function formatNumber(n) {
  const rounded = n === 0 ? 0 : Number(n.toPrecision(10))
  return String(rounded)
}
"}

