{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e9-preset-craft-vs-plain-t5-20260919T125605Z/cell-p60sZf/src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js values` prints the value of every cell in the
 * sheet read from standard input, and `node src/cli.js deps` prints the cells
 * each one reads.
 */

import { readFileSync } from 'node:fs'
import { parseSheet, SheetError } from './sheet.js'
import { readAddressWord, compareAddr } from './address.js'
import { parseFormula } from './parser.js'
import { collectDeps } from './deps.js'
import { Evaluator, formatValue } from './evaluate.js'

function fail(message) {
  process.stderr.write(message + '\n')
  process.exit(2)
}

function main() {
  const mode = process.argv[2]
  if (process.argv.length !== 3 || (mode !== 'values' && mode !== 'deps')) {
    fail('error: usage: cli.js values|deps')
  }

  const input = readFileSync(0, 'utf8')

  let cells
  try {
    cells = parseSheet(input)
  } catch (e) {
    if (e instanceof SheetError) fail(e.message)
    throw e
  }

  const addresses = [...cells.keys()]
    .map((label) => readAddressWord(label))
    .sort(compareAddr)
    .map((a) => a.label)

  const lines = []
  if (mode === 'values') {
    const evaluator = new Evaluator(cells)
    for (const address of addresses) {
      lines.push(`${address}=${formatValue(evaluator.getValue(address))}`)
    }
  } else {
    for (const address of addresses) {
      const content = cells.get(address)
      let deps = []
      if (content.startsWith('=')) {
        const ast = parseFormula(content.slice(1))
        if (ast !== null) deps = collectDeps(ast)
      }
      lines.push(`${address}: ${deps.join(' ')}`.trimEnd())
      if (deps.length > 0) lines[lines.length - 1] = `${address}: ${deps.join(' ')}`
    }
  }
  process.stdout.write(lines.map((l) => l + '\n').join(''))
}

main()
